<script setup lang="ts">
import {title as displayTitle,sourceName,indicator,utc,time as beijingTime,duration,http} from '../presentation/zh';
import {ref,watch} from 'vue';import {post} from '../api/client';const props=defineProps<{token:string;eventId?:string}>();const config=ref<Record<string,any>>({}),rows=ref<Record<string,any>[]>([]),busy=ref(false),error=ref('');
function decode(v:any){try{return JSON.parse(v?.value??v)}catch{return v}}
async function load(){try{config.value=await post('/ai/status',props.token);rows.value=props.eventId?await post('/ai/history',props.token,{eventId:props.eventId}):[];}catch{error.value='AI 配置与分析记录暂不可用';}}
async function analyze(){busy.value=true;error.value='';try{await post('/ai/analyze',props.token,{eventId:props.eventId});await load();}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
watch(()=>props.eventId,()=>void load(),{immediate:true});
</script>
<template><section class="ai-analysis"><h3>证据约束的智能研判</h3><p>{{config.state||'正在读取实际配置'}} · 实际执行 {{config.executions??'未取得'}} 次</p><p>人工智能（AI）产物保持待人工审核；字段一致性检查不代表事实、企业关系或市场影响已核实。</p><p v-if="error" role="alert">{{error}}</p><button v-if="eventId" :disabled="busy||!config.configured" @click="analyze">{{busy?'正在分析真实证据…':'分析当前官方事件证据'}}</button><p v-if="!rows.length">暂无实际模型分析</p><article v-for="r in rows" :key="r.analysis_id"><p>分析 {{r.analysis_id}} · 模型 {{r.model_id}} · 提示版本 {{r.prompt_version}} · {{r.status==='COMPLETED'?'已返回，待审核':r.status==='FAILED'?'执行失败':'执行中'}}</p><p>生成时间 <time :title="'UTC原值：'+utc(r.generated_at)">{{beijingTime(r.generated_at,'未生成')}}</time> · {{r.numeric_validation==='PASS'?'字段引用一致性检查通过':r.numeric_validation==='REVIEW_REQUIRED'?'证据或数字口径需人工核查':'未通过或尚未检查'}}</p><p v-if="r.status==='COMPLETED'&&r.translated_title">机器翻译 · 模型执行记录 {{r.analysis_id}} · 待人工审核；官方原文见事件证据。</p><h4>{{r.status==='COMPLETED'&&r.analysis_id&&r.translated_title?r.translated_title:'中文翻译待完成'}}</h4><p>{{r.status==='COMPLETED'&&r.analysis_id&&r.summary?r.summary:'尚无成功模型执行生成的摘要'}}</p><details><summary>提取事实、原文引用与影响假设</summary><pre>{{decode(r.extracted_facts)}}</pre><pre>{{decode(r.hypotheses)}}</pre><p>输入证据 {{r.input_evidence_ids}}</p></details><h4>不确定性与反证</h4><pre>{{decode(r.uncertainties)}}</pre><pre>{{decode(r.counter_evidence)}}</pre></article></section></template>
<style scoped>pre{white-space:pre-wrap;overflow-wrap:anywhere}.ai-analysis{margin-top:20px;border-top:1px solid #324258;padding-top:12px}article{overflow-wrap:anywhere}</style>
